/// @title  MemeToken — template générique de lancement memecoin
/// @notice ERC-20 sur Robinhood Chain. 100% du supply mint au déployeur au
///         constructeur, pour dépôt en position Uniswap v3 single-sided.
///         Pas de vault, pas de taxe, pas de rewards, pas d'oracle.
/// @dev    NON AUDITÉ. Voir bandeau d'avertissement en tête de fichier.
contract MemeToken is MemeERC20, MemeOwnable {
    // ───────────────────────────────────────────────────────────────────────
    //  IMMUTABLES — fixés au déploiement
    // ───────────────────────────────────────────────────────────────────────
    uint256 public immutable totalSupplyMinted;

    // ───────────────────────────────────────────────────────────────────────
    //  STATE — pool (settable une fois, avant renounce)
    // ───────────────────────────────────────────────────────────────────────
    address public uniswapV3Pool;

    // ───────────────────────────────────────────────────────────────────────
    //  EVENTS
    // ───────────────────────────────────────────────────────────────────────
    event PoolSet(address indexed pool);

    // ═══════════════════════════════════════════════════════════════════════
    //  MÉTADONNÉES ON-CHAIN — format Pons (Robinhood Chain)
    //
    //  La struct et la signature de getTokenInfo() reproduisent EXACTEMENT
    //  celles du launchpad Pons, que Mobula et Bitquery savent déjà décoder.
    //  Ne pas réordonner les champs, ne pas renommer la fonction : c'est le
    //  seul intérêt de ce format — un intégrateur n'a aucun décodeur à
    //  écrire, il n'a qu'à ajouter l'adresse de notre factory à son
    //  adaptateur existant.
    //
    //  Tout est posé au CONSTRUCTEUR et jamais modifiable ensuite. La factory
    //  renonce à la propriété du token dans la même transaction : il n'existe
    //  donc aucune fenêtre où quelqu'un pourrait réécrire ces champs, et
    //  aucune étape à ne pas oublier après coup.
    // ═══════════════════════════════════════════════════════════════════════
    struct Socials {
        string twitter;
        string telegram;
        string discord;
        string website;
        string farcaster;
    }

    /// @notice Longueur maximale d'une URI, en octets. Le logo est stocké
    ///         comme URL, jamais comme octets d'image : une image 128x128 en
    ///         base64 coûterait ~3,5 M de gas, prohibitif sur Ethereum.
    uint256 public constant MAX_URI_LENGTH = 256;
    /// @notice Longueur maximale de la description, en octets.
    uint256 public constant MAX_DESCRIPTION_LENGTH = 512;

    /// @notice La factory qui a créé ce token. Immuable, posée au constructeur.
    /// @dev    Moitié du liage bidirectionnel : le token dit d'où il vient,
    ///         et la factory confirme via isLaunchedHere(). C'est ce couple
    ///         qui permet à un scanner d'attribuer le token au launchpad —
    ///         sans lui, rien à vérifier, d'où les « Factory: Unknown ».
    address public immutable factory;

    address private immutable _tokenDeployer;
    string  private _tokenLogo;
    string  private _tokenDescription;
    Socials private _tokenSocials;

    // ───────────────────────────────────────────────────────────────────────
    //  CONSTRUCTOR
    // ───────────────────────────────────────────────────────────────────────
    /// @param name_          Nom du token
    /// @param symbol_        Ticker du token
    /// @param totalSupply_   Quantité totale à minter (en unités entières, ex. 1_000_000_000)
    /// @param tokenDeployer_ Portefeuille qui a signé le lancement (le créateur,
    ///                       pas la factory)
    /// @param logo_          URI du logo — ar:// ou ipfs:// uniquement, jamais les octets
    /// @param description_   Description libre du projet
    /// @param socials_       Liens sociaux (https:// uniquement), ordre imposé par le format Pons
    constructor(
        string memory name_,
        string memory symbol_,
        uint256 totalSupply_,
        address tokenDeployer_,
        string memory logo_,
        string memory description_,
        Socials memory socials_
    )
        MemeERC20(name_, symbol_)
        MemeOwnable(msg.sender)
    {
        require(totalSupply_ > 0, "MemeToken: Invalid supply");
        // FIX (H001 — IMPROPER VALIDATION IN REQUIRE STATEMENTS) : seule une
        // borne basse était vérifiée. `totalSupply_ * 1e18` reverte déjà
        // automatiquement en cas d'overflow (Solidity 0.8, arithmétique
        // checked), donc aucun fonds n'était à risque — mais l'absence de
        // borne haute explicite laissait passer des valeurs qui n'ont aucun
        // sens économique et qui feraient revert loin de ce constructeur
        // (dans _computeSqrtPriceX96 côté factory), rendant l'erreur difficile
        // à diagnostiquer pour un appelant. 1e50 reste extrêmement généreux
        // (aucun memecoin réaliste n'approche cette supply) tout en donnant
        // un message d'erreur clair, tôt, au bon endroit.
        require(totalSupply_ <= 1e50, "MemeToken: Supply too large");

        totalSupplyMinted = totalSupply_ * 1e18;

        _mint(msg.sender, totalSupplyMinted);

        // ── Métadonnées, posées une fois pour toutes ────────────────────
        // msg.sender EST la factory : ce token n'est déployé que par elle.
        factory        = msg.sender;
        _tokenDeployer = tokenDeployer_;

        _checkLogo(logo_);
        _checkHttps(socials_.twitter,   "twitter");
        _checkHttps(socials_.telegram,  "telegram");
        _checkHttps(socials_.discord,   "discord");
        _checkHttps(socials_.website,   "website");
        _checkHttps(socials_.farcaster, "farcaster");
        if (bytes(description_).length > MAX_DESCRIPTION_LENGTH) {
            revert FieldTooLong("description", bytes(description_).length, MAX_DESCRIPTION_LENGTH);
        }

        _tokenLogo        = logo_;
        _tokenDescription = description_;
        _tokenSocials     = socials_;
    }

    // ── Erreurs de validation — mêmes noms et mêmes arguments que dans
    //    TokenMetadataRegistry (projet $MHT V3) : un seul vocabulaire
    //    d'erreurs pour tous les jetons ApexPad, Factory ou manuels.
    /// @notice Schéma refusé. Logo : ar:// ou ipfs://. Réseaux : https://.
    ///         Un préfixe seul, sans rien derrière, est aussi refusé.
    error InvalidScheme(string field);
    error FieldTooLong(string field, uint256 length, uint256 maxLength);

    /// @notice Logo : vide, ou ar:// / ipfs:// — JAMAIS https://.
    /// @dev    Décision du 10/09/2026. Une URL https peut changer de contenu
    ///         en silence après le lancement (bait-and-switch), alors que
    ///         l'enregistrement on-chain, lui, est définitif. Un lien
    ///         content-addressé ne peut que mourir, jamais changer — et
    ///         mourir se rattrape : n'importe qui peut ré-héberger les mêmes
    ///         octets sous le même identifiant.
    function _checkLogo(string memory uri) private pure {
        bytes memory b = bytes(uri);
        if (b.length == 0) return;                       // facultatif
        if (b.length > MAX_URI_LENGTH) revert FieldTooLong("logo", b.length, MAX_URI_LENGTH);
        if (!_hasPrefix(b, "ar://") && !_hasPrefix(b, "ipfs://")) revert InvalidScheme("logo");
    }

    /// @notice Réseaux sociaux : vide, ou https:// uniquement.
    /// @dev    Le contrôle de schéma n'est pas cosmétique. Ces chaînes sont
    ///         réinjectées dans des <a href> par le catalogue et les pages de
    ///         preuve : sans ce garde-fou, une URI `javascript:` ou `data:`
    ///         donnerait une exécution de script sur nos propres pages. Le
    ///         refuser ici ferme la porte pour tous les consommateurs,
    ///         présents et futurs. On ne met pas un Telegram sur IPFS : la
    ///         règle est donc PAR CHAMP, pas globale.
    function _checkHttps(string memory uri, string memory field) private pure {
        bytes memory b = bytes(uri);
        if (b.length == 0) return;                       // facultatif
        if (b.length > MAX_URI_LENGTH) revert FieldTooLong(field, b.length, MAX_URI_LENGTH);
        if (!_hasPrefix(b, "https://")) revert InvalidScheme(field);
    }

    /// @dev Vrai si `b` commence par `prefix` ET contient au moins un octet de
    ///      plus : « ar:// » tout seul n'est pas un logo. Sensible à la casse,
    ///      volontairement : « HTTPS:// » est refusé. Même règle que
    ///      TokenMetadataRegistry._startsWith.
    function _hasPrefix(bytes memory b, string memory prefix) private pure returns (bool) {
        bytes memory p = bytes(prefix);
        if (b.length <= p.length) return false;
        for (uint256 i = 0; i < p.length; ++i) {
            if (b[i] != p[i]) return false;
        }
        return true;
    }

    /// @notice Métadonnées complètes du token, en un seul appel.
    /// @dev    Signature reprise au caractère près du launchpad Pons pour que
    ///         les adaptateurs Mobula/Bitquery existants la décodent sans
    ///         modification. Ne pas renommer, ne pas réordonner.
    function getTokenInfo() external view returns (
        address tokenDeployer,
        string memory tokenLogo,
        string memory tokenDescription,
        Socials memory tokenSocials
    ) {
        return (_tokenDeployer, _tokenLogo, _tokenDescription, _tokenSocials);
    }

    // ═══════════════════════════════════════════════════════════════════════
    //  CONFIGURATION — appelé une fois après deploy, avant renounceOwnership()
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Renseigne la pool Uniswap v3, une fois créée. Purement
    ///         informatif/vérifiable on-chain — plus aucune logique de
    ///         _update() ne dépend de cette adresse depuis le retrait du
    ///         verrou de lancement et de l'anti-sandwich (voir en-tête).
    function setPool(address pool) external onlyOwner {
        require(pool != address(0), "MemeToken: Invalid pool");
        require(uniswapV3Pool == address(0), "MemeToken: Pool already set");
        uniswapV3Pool = pool;
        emit PoolSet(pool);
    }

    // ═══════════════════════════════════════════════════════════════════════
    //  Pas d'override de _update() : transferts standard OZ-style, sans
    //  aucune condition liée à la pool, au timing, ou au bloc. C'est le
    //  MemeERC20._update() hérité tel quel qui s'applique.
    // ═══════════════════════════════════════════════════════════════════════
}
